if(order==='brace'){if(already('brace'))throw new RangeError('Brace For Impact only once per round');const check=checkOrder(systemsBonus(ship),10);d.ordersUsed.brace=round;if(check.success)d.braceRound=round;return {...result,check,braceActive:check.success}}
if(order==='route'){if(control>0)throw new RangeError('Route Control requires destroyed Control');if(already('route'))throw new RangeError('Route Control only once per round');const check=checkOrder(technicalBonus(ship,'Control').bonus,25);d.ordersUsed.route=round;if(check.success){d.remaining.Control=1;d.destroyed.Control=false;d.impaired.Control=true}return {...result,check,remaining:d.remaining.Control}}
if(!['online','hold'].includes(order))throw new RangeError('Unknown damage-control order');if(!control)throw new RangeError('Restore Control with Route Control first');
if(!['Engines','Control','Hangar','Weapons','Special'].includes(area))throw new RangeError('This area cannot be repaired in battle');
if(area==='Weapons'&&(!Number.isInteger(weaponIndex)||weaponIndex<0||weaponIndex>=ship.stats.weapons.length))throw new RangeError('Choose a weapon mount');
if(area==='Special'&&order==='hold')throw new RangeError('Lost features require Get Those Systems Back Online');
if(already(order+':'+key))throw new RangeError('This system already received this order this round');
if(order==='hold'&&d.materialsExhausted.includes(key))throw new RangeError('Repair materials exhausted for this system');
const current=area==='Weapons'?weaponSpaces(ship,weaponIndex):d.remaining[area],maximum=area==='Weapons'?ship.stats.weapons[weaponIndex].spaces:d.initial[area];
if(area==='Special'){if(!d.destroyedFeatures.length)throw new RangeError('No destroyed feature to restore')}
else if(order==='online'&&current>0)throw new RangeError('Get Those Systems Back Online requires a destroyed system');
else if(order==='hold'&&(current<=0||current>=maximum&&!((area==='Weapons'?d.impairedWeapons.includes(weaponIndex):d.impaired[area]))))throw new RangeError('Hold Her Together requires a damaged but surviving system');
