function sqlShip(db,s,gameId,op){return db.prepare('UPDATE ships SET range_band=?,remaining=?,actions_left=?,handling_lost=?,attack_penalty=?,dodge_bonus=?,status=?,stats_json=? WHERE id=? AND game_id=? AND EXISTS(SELECT 1 FROM games WHERE id=? AND last_op_id=?)').bind(s.range_band,s.remaining,s.actions_left,s.handling_lost,s.attack_penalty,s.dodge_bonus,s.status,JSON.stringify({...s.stats,combatState:{interceptors:s.interceptorScreen||[],interceptorsUsed:s.interceptorsUsed||[],lockedTarget:s.lockedTarget||null}}),s.id,gameId,gameId,op)}
